.cr_sc_classes<-list(ABS=c('CONSUMER_LOAN','AUTO_LOAN','LEASE'),RMBS='RESIDENTIAL_MORTGAGE',CMBS='COMMERCIAL_MORTGAGE',CLO='CORPORATE_LOAN',MORTGAGE_COVER=c('RESIDENTIAL_MORTGAGE','COMMERCIAL_MORTGAGE'),PUBLIC_SECTOR_COVER='PUBLIC_SECTOR_CLAIM',TRADE_RECEIVABLES='INVOICE')
